B.Dj=new A.bm("dart-03-tipos-datos","Dart b\xe1sico","03 \xb7 Tipos de datos b\xe1sicos","Principiante","Trabaja con int, double, num, String, bool, Object y dynamic.","Un tipo correcto documenta el c\xf3digo y evita operaciones inv\xe1lidas.","void main() {\n  int unidades = 4;\n  double precio = 19.95;\n  num descuento = 5;\n  String categoria = 'Libros';\n  bool disponible = true;\n  Object dato = 'texto seguro';\n  dynamic flexible = 10;\n\n  print(unidades.runtimeType);\n  print('$categoria - $disponible');\n  print(dato);\n  print(flexible);\n}",B.Mq,"Representa un estudiante con nombre, edad, promedio, estado activo y c\xf3digo.",B.Lk,4284524026)
B.Kh=s(["Usa +, -, *, /, ~/ y %.","Compara con ==, !=, >, <, >= y <=.","Combina con &&, || y !.","Usa el ternario para decisiones peque\xf1as."],t.s)
B.Jh=s(["operadores","aritmetica","comparacion","logicos","ternario"],t.s)
B.CN=new A.bm("dart-04-operadores","Dart b\xe1sico","04 \xb7 Operadores","Principiante","Practica operadores aritm\xe9ticos, comparaci\xf3n, asignaci\xf3n, l\xf3gicos y ternarios.","Los operadores permiten calcular, comparar y construir condiciones.","void main() {\n  var a = 10;\n  var b = 3;\n  print(a + b);\n  print(a - b);\n  print(a * b);\n  print(a / b);\n  print(a ~/ b);\n  print(a % b);\n\n  final cumple = a >= 10 && b != 0;\n  final mensaje = cumple ? 'V\xe1lido' : 'No v\xe1lido';\n  print(mensaje);\n}",B.Kh,"Determina si una persona puede entrar a un evento seg\xfan edad y entrada v\xe1lida.",B.Jh,4284524026)
B.LF=s(["Crea String con comillas simples o dobles.","Interpola con $variable y ${expresion}.","Usa \\n para un salto de l\xednea.","Practica trim(), contains(), toUpperCase() y split()."],t.s)
B.M3=s(["string","interpolacion","texto","metodos"],t.s)
